style.css:
/* High-Tech Metal Background */
body:has(main) {
    background: repeating-linear-gradient(
        45deg, 
        #0a0f1f, #1b2b3a 10%, #0a0f1f 20%
    ) !important;
    background-size: 400% 400%;
    animation: metalShine 8s infinite linear;
}

/* Brushed Metal Shine Effect */
@keyframes metalShine {
    0% { background-position: 0% 50%; }
    100% { background-position: 100% 50%; }
}

/* Main Chat Container */
main {
    background: rgba(15, 20, 30, 0.95) !important;
    border: 2px solid #008cff !important;
    box-shadow: 0 0 10px #008cff, 0 0 20px #008cff !important;
    border-radius: 10px !important;
}

/* Chat Bubbles */
[class*="prose"] {
    background: rgba(0, 140, 255, 0.1) !important;
    border-left: 3px solid #008cff !important;
    padding: 15px !important;
    margin: 5px 0 !important;
    border-radius: 5px !important;
}

/* User Messages */
div[class*="prose"] p {
    color: #ffffff !important;
    text-shadow: 0 0 5px #ffffff, 0 0 10px #ffffff !important;
}

/* AI Messages */
div[class*="markdown"] {
    color: #008cff !important;
    text-shadow: 0 0 5px #008cff !important;
}

/* Input Box */
textarea {
    background: rgba(10, 15, 25, 0.9) !important;
    border: 1px solid #008cff !important;
    color: #ffffff !important;
    text-shadow: 0 0 5px #ffffff !important;
}

/* Buttons - Blue Theme */
button {
    background: linear-gradient(45deg, #0055cc, #008cff) !important;
    border: none !important;
    color: white !important;
    padding: 12px 22px !important;
    border-radius: 6px !important;
    cursor: pointer !important;
    text-shadow: 0 0 5px white !important;
    margin: 10px !important;
}

button:hover {
    box-shadow: 0 0 12px #008cff, 0 0 24px #008cff !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px !important;
}

::-webkit-scrollbar-thumb {
    background: #008cff !important;
    border-radius: 10px !important;
}

::-webkit-scrollbar-track {
    background: #0a0f1f !important;
}
